import { ModuleItem } from 'src/components/CustomPage/interface';
import { getContextToFileData, paramToStringify } from 'src/utils/code';
import { InterfaceToSchema } from 'src/utils/transform';
import { getTypeContext } from 'src/utils/tsMorph';
import _ from 'lodash';
import React from 'react';

class ContextStore {

    item: ModuleItem;
    isSave = false;

    constructor(item: ModuleItem){
        this.item = item;
    }


    /**
     * 获取当前页面文本列表（ index.tsx、store.tsx ) 文件
     */
    getTextFiles = async () => {
        const text = await getContextToFileData(this.item)

        return text;
    }

    /**
     * 文本解析
     */
    parseFileToData = async (text) => {
        const objs = await getTypeContext(text);
        const { interfaces, default: defaultValue } = objs;
        if(defaultValue){
            const value = paramToStringify(eval(defaultValue));
            _.set(this.item, 'extraInfo.default', value);
        }
        if(interfaces){
            const schema = InterfaceToSchema(interfaces[0]);
            _.set(this.item, 'props', schema);
        }
        this.isSave = true;
    }
}

export default ContextStore;